controller=new ControllerInput({action:(action,down)=>{if(!document.hidden&&view==='play'&&!document.querySelector('dialog[open]')){if(down)sound.unlock();game.action(action,down);}},isMenu:()=>document.hidden||view!=='play'||!!document.querySelector('dialog[open]')||!$('#game-overlay').hidden,menu:controllerMenu,disconnected:()=>{game.clearInput();if(game.status==='playing')pause();toast('Controller disconnected. Keyboard controls remain available.');},connected:()=>toast('Controller connected: A jump, Y retry, Start pause, Back map.')});controller.deadzone=controls.deadzone;
