 const initial=game.endless?.seed||new URL(location.href).searchParams.get('endless')||new Date().toISOString().slice(0,10);let bests=[];try{bests=JSON.parse(storage.getItem('endless-bests')||'[]');if(!Array.isArray(bests))bests=[];}catch{}
 $('#modal').dataset.kind='endless';$('#modal-eyebrow').textContent='A NEW ADVENTURE';$('#modal-content').innerHTML=`<h2>${IS_KIDS?'Cloud chase':'Endless pursuit'}</h2><p>Keep moving right. ${IS_KIDS?'A sleepy cloud':'Fire'} follows from the left. Pausing also pauses the pursuit. Same seed, difficulty and generator give the same route. Climb the terraces and choose your landings. A raised exit about every 500m lets you finish safely; stay on the floor to continue. Every fifth stretch is a breather.</p><form id="endless-form" class="setup-form"><label>Seed<input name="seed" maxlength="48" required value="${esc(initial)}"></label><label>Difficulty<select name="difficulty">${['easy','medium','hard'].map(d=>`<option value="${d}" ${d===(game.endless?.difficulty||'medium')?'selected':''}>${d}</option>`).join('')}</select></label><label class="check-row"><input type="checkbox" name="assisted" ${game.endless?.assisted?'checked':''}> Assisted practice: one free charge of each helper</label><p class="muted">Local bests are separate for each seed, difficulty and helper policy. No campaign rewards or online ranking. ${ENDLESS_VERSION}.</p><button class="primary">Start endless</button></form><h3>Recent local bests</h3><ul>${bests.slice(0,10).map(r=>`<li>${esc(r.seed)} · ${esc(r.difficulty)} · ${r.assisted?'assisted':'no helpers'} · ${(Number(r.distance)/30).toFixed(1)}m</li>`).join('')||'<li>No finished runs yet.</li>'}</ul>`;
 $('#endless-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);$('#modal').close();launchEndless({seed:f.get('seed'),difficulty:f.get('difficulty'),assisted:f.has('assisted')});};if(!$('#modal').open)$('#modal').showModal();
