async function submitCompetitionResult(){
 const race=competitionRun;if(!race?.pending||race.submitting)return;race.submitting=true;const button=$('#game-overlay .primary');if(button){button.disabled=true;button.textContent='Verifying replay…';}
 try{const result=await api(`/v1/attempts/${race.attempt.id}/submit`,{method:'POST',data:{position:communityRun.index,levelHash:race.event.snapshot[communityRun.index].hash,replay:race.pending.replay}});if(competitionRun!==race)return;race.attempt=result.attempt;race.pending=null;$('#game-overlay .overlay-card p').textContent=result.attempt.status==='completed'?`Verified finish · ${(result.attempt.total_ms/1000).toFixed(2)}s server elapsed.`:'Replay verified. The event clock is still running.';if(button){button.textContent=result.attempt.status==='completed'?'Back to community':'Next event level';button.disabled=false;}}
 catch(error){if(competitionRun!==race)return;$('#game-overlay .overlay-card p').textContent=error.message;if(button){button.disabled=false;button.textContent='Retry submission';}if(error.status===400){race.pending=null;if(button){button.dataset.action='retry';button.textContent='Retry level';}}}
 finally{race.submitting=false;}
}
