const actions={'test-arena':()=>openTestArena(),'arena-warp':()=>openTestArena($('#arena-zone').value),'editor-undo':()=>restoreEditorHistory(false),'editor-redo':()=>restoreEditorHistory(true),'editor-copy':()=>copyEditorSelection(),'editor-paste':()=>pasteEditorSelection(),dressing:()=>showModal('dressing'),endless:()=>endlessMenu(), 'campaign':()=>{loadLevel(levelIndex);navigate('play');},'upload-score':()=>{if(lastFinishedRun)highscores.share(lastFinishedRun);},'online-scores':()=>{if(game.status==='playing')pause();highscores.browse(levelIndex,state.settings.difficulty);},community:()=>{if(game.status==='playing')pause();onlineWorkshop.open('community');},'ai-create':()=>onlineWorkshop.open(),'export-reviews':()=>download({schemaVersion:1,gameVersion:APP_VERSION,reviews:playtestNotes},'blood-and-balance-playtest-reviews.json'),'clear-jump':()=>{jumpPin=null;jumpCache=null;syncEditorInspector();drawEditor();},'copy-campaign':()=>{download(editor,'workshop-backup.n-level.json');editor=structuredClone(campaignLevel(Number($('#editor-campaign-stage').value)));editor.name+=' (copy)';jumpPin=null;jumpCache=null;saveDraft();navigate('editor');toast('Campaign copy loaded. Previous draft downloaded; campaign unchanged.');},'exit-rule':()=>{const id=$('#editor-circuit').value,on=$('#exit-state').value;if(!(editor.switches??[]).some(s=>s.id===id)){toast('Place this switch or lever first.');return;}upgradeEditor();editor.version=3;editor.exitStates??={};editor.exitRequires=editor.exitRequires.filter(key=>key!==id);if(on==='ignore')delete editor.exitStates[id];else editor.exitStates[id]=on==='true';saveDraft();drawEditor();},start,pause,retry,map:()=>game.cycleMap(),fullscreen:()=>{const request=document.fullscreenElement?document.exitFullscreen?.():$('.game-column').requestFullscreen?.();if(request)request.catch(()=>toast('Fullscreen is not available in this browser.'));else toast('Fullscreen is not available in this browser.');},levels:()=>showModal('levels'),shop:()=>showModal('shop'),help:()=>showModal('help'),options:()=>showModal('options'),career:()=>showModal('career'),close:()=>$('#modal').close(),next:()=>{if(competitionRun){if(competitionRun.pending){submitCompetitionResult();return;}if(competitionRun.attempt.status==='completed'){competitionRun=null;communityRun=null;onlineWorkshop.open('community');return;}communityRun.index=competitionRun.attempt.progress;loadCommunityRoom();return;}if(communityRun){if(communityRun.index+1<communityRun.levels.length){communityRun.index++;loadCommunityRoom();}else onlineWorkshop.open('community');}else if(custom)navigate('editor');else if(levelIndex===98)navigate('records');else{loadLevel(levelIndex+1);start();}},sound:()=>{state.settings.sound=!state.settings.sound;sound.unlock();sound.play('click');save();refresh();},music:()=>{state.settings.music=!state.settings.music;sound.unlock();save();refresh();},import:()=>$('#import-file').click(),export:()=>{try{const l=validateLevel(editor);download(l,`${l.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')||'level'}.n-level.json`);toast('Level exported. Ready to pass on.');}catch(e){toast(e.message);}},test:()=>{try{const l=validateLevel(editor);finishCommunityAttempt('abandoned');communityRun=null;competitionRun=null;chapterRun=null;custom=true;navigate('play');game.load(l,1,l.coins.map((_,i)=>i));setStage();overlay('ready');refresh();}catch(e){toast(e.message);}},'new-level':()=>{download(editor,'workshop-backup.n-level.json');editor=emptyLevel();jumpPin=null;jumpCache=null;saveDraft();navigate('editor');toast('Fresh canvas. Previous draft downloaded as a backup.');},'share-score':()=>{download(scorePayload(state,{playerName:state.settings.playerName,gameVersion:APP_VERSION,gitHash:GIT_HASH}),'blood-and-balance-scores.json');toast('Personal bests exported for the future leaderboard API.');},'reload-update':()=>location.reload()};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;sound.unlock();if(b.dataset.career){const selected=selectCareer(careerBook,b.dataset.career);if(selected){activeCareer=selected;failedStages.clear();state=selected.progress;sound.settings=state.settings;custom=false;navigate('play');levelIndex=careerStartStage(selected);loadLevel(levelIndex);$('#modal').close();}}if(b.dataset.outfitPreview)drawDressingPreview($('#outfit-preview'),state,b.dataset.outfitPreview);if(b.dataset.outfitItem){const id=b.dataset.outfitItem,item=ACCESSORIES.find(a=>a.id===id);if(item&&(state.ownedAccessories?.includes(id)?equipAccessory(state,item.slot,id):buyAccessory(state,id))){save();refresh();renderModal('dressing');}}if(b.dataset.outfitRemove){equipAccessory(state,b.dataset.outfitRemove,null);save();refresh();renderModal('dressing');}if(b.dataset.outfitSkin&&unlockedCosmetics(state).skins.some(s=>s.id===b.dataset.outfitSkin)){state.settings.skin=b.dataset.outfitSkin;save();refresh();renderModal('dressing');}if(b.dataset.action)actions[b.dataset.action]?.();if(b.dataset.themeChoice){theme=setTheme(storage,document.documentElement,b.dataset.themeChoice);renderModal('options');}if(b.dataset.paletteChoice){const option=PALETTES.find(p=>p.id===b.dataset.paletteChoice),available=unlockedCosmetics(state).palettes;if(option&&available.includes(option)){state.settings.palette=option.id;document.documentElement.dataset.palette=option.id;save();renderModal('options');}}if(b.dataset.skinChoice){const option=SKINS.find(p=>p.id===b.dataset.skinChoice),available=unlockedCosmetics(state).skins;if(option&&available.includes(option)){state.settings.skin=option.id;game.skin=option.id;save();renderModal('options');}}if(b.dataset.toggleSetting){state.settings[b.dataset.toggleSetting]=!state.settings[b.dataset.toggleSetting];sound.settings=state.settings;sound.unlock();sound.sync();save();renderModal('options');refresh();}if(b.dataset.nav)navigate(b.dataset.nav);if(b.dataset.level!==undefined&&unlocked(state,+b.dataset.level,testingMode)){$('#modal').close();navigate('play');loadLevel(+b.dataset.level);}if(b.dataset.item)useItem(b.dataset.item);if(b.dataset.buy&&buy(state,b.dataset.buy)){save();refresh();renderModal('shop');sound.play('gold');}if(b.dataset.tool){tool=b.dataset.tool;document.querySelectorAll('[data-tool]').forEach(el=>el.classList.toggle('active',el.dataset.tool===tool));syncEditorInspector();drawEditor();}});
$('.brand').addEventListener('click',e=>{e.preventDefault();navigate('play');});
$('#modal-content').addEventListener('submit',e=>{if(e.target.id!=='new-career-form')return;e.preventDefault();const form=new FormData(e.target),name=String(form.get('name')||'').trim().slice(0,24);if(!name){toast('Choose a name for this career.');return;}let created;try{created=createCareer(careerBook,name,form.get('difficulty'));}catch(error){toast(error.message);return;}activeCareer=created;failedStages.clear();state=created.progress;sound.settings=state.settings;navigate('play');levelIndex=careerStartStage(created);loadLevel(levelIndex);save();checkForUpdate();setInterval(checkForUpdate,300000);$('#modal').close();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
for(const b of document.querySelectorAll('[data-key]')){b.addEventListener('pointerdown',e=>{e.preventDefault();sound.unlock();b.setPointerCapture(e.pointerId);game.input(b.dataset.key,true);});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>game.input(b.dataset.key,false));}
loadLevel(levelIndex);save();checkForUpdate();if(!IS_KIDS&&new URL(location.href).searchParams.has('community')||!IS_KIDS&&new URL(location.href).searchParams.has('competition')||!IS_KIDS&&new URL(location.href).searchParams.has('lobby'))onlineWorkshop.open('community');

$('#playtest-note').addEventListener('submit',e=>{e.preventDefault();if(custom)return;const data=new FormData(e.target);try{playtestNotes=saveNote(storage,playtestNotes,{stage:levelIndex+1,revision:campaignRevision(levelIndex),difficulty:state.settings.difficulty,rating:String(data.get('rating')),note:String(data.get('note')),starts:state.levelPlays[levelIndex]||0,best:state.completed[levelIndex]?.best??null,updatedAt:new Date().toISOString()});refresh();toast('Stage review saved locally.');}catch{toast('Could not save the review. Browser storage is unavailable.');}});

let lobbyPollBusy=false;
setInterval(async()=>{const race=competitionRun;if(!race?.lobbyId||race.liveComplete||Date.now()>race.attempt.deadline+5000||lobbyPollBusy)return;lobbyPollBusy=true;try{const room=await api(`/v1/lobbies/${race.lobbyId}`);if(competitionRun===race){race.liveProgress=room.members;race.liveComplete=['closed','finished'].includes(room.state);if(['closed','finished'].includes(room.state)&&race.attempt.status==='active'&&room.race?.attempt.status!=='active'){race.attempt=room.race?.attempt||race.attempt;toast('Race room finished. Open the room to see results.');}}}catch{/* A disconnect keeps the authoritative race clock running. */}finally{lobbyPollBusy=false;}},3000);
